import type {
  AgentSelectionContext,
  AgentTool,
  AgentToolResult,
  AgentToolSchema,
} from '@/lib/agent-types'
import {
  documentOf,
  hideOthersOf,
  type PropertySnapshot,
  parseHexColor,
  plural,
  RESULT_TEXT_LIMIT,
  ToolInputError,
  throwIfAborted,
  truncateResultText,
  type ViewerAgentDocument,
  type ViewerAgentModel,
  type ViewerAgentViewer,
  type ViewerMath,
  type ViewerStateFilter,
  type ViewerToolKit,
  type ViewerToolSpec,
  validateToolInput,
} from '@/lib/viewer-agent-core'
import { displayTools } from '@/lib/viewer-agent-display'
import { inspectionTools } from '@/lib/viewer-agent-inspect'
import {
  loadPropertySnapshot,
  QuerySandbox,
  type QueryWorkerHandle,
} from '@/lib/viewer-agent-query'
import {
  buildElementIndex,
  ColorLedger,
  type ElementIndex,
  ElementSetStore,
  UndoStack,
  type ViewerSnapshot,
} from '@/lib/viewer-agent-state'

export type {
  ViewerAgentModel,
  ViewerAgentViewer,
  ViewerMath,
} from '@/lib/viewer-agent-core'
export type { QueryWorkerHandle } from '@/lib/viewer-agent-query'
export {
  ColorLedger,
  type ColorLegendEntry,
  ElementSetStore,
  type UndoEntry,
  UndoStack,
} from '@/lib/viewer-agent-state'

export type ViewerAgentTool = AgentTool

export interface ViewerAgentToolsOptions {
  /** THREE constructors; defaults to the viewer runtime's global THREE. */
  math?: ViewerMath
  /** Characters of tool output the model reads before the truncation note. */
  resultTextLimit?: number
  queryTimeoutMs?: number
  /** Property pairs above which run_query refuses to copy the database. */
  queryMaxPairs?: number
  createQueryWorker?: () => QueryWorkerHandle
  now?: () => number
}

export interface ViewerAgentTools {
  tools: ViewerAgentTool[]
  sets: ElementSetStore
  undo: UndoStack
  colors: ColorLedger
  instructions: string
  describeSelection(dbIds?: readonly number[]): Promise<AgentSelectionContext>
  dispose(): void
}

const KEEP_CAMERA: ViewerStateFilter = {
  seedURN: true,
  objectSet: true,
  renderOptions: true,
  cutplanes: true,
}

const defaultMath: ViewerMath = {
  vector3: (x, y, z) => new THREE.Vector3(x, y, z),
  vector4: (x, y, z, w) => new THREE.Vector4(x, y, z, w),
  box3: () => new THREE.Box3(),
}

export const VIEWER_AGENT_INSTRUCTIONS = `You work inside an Autodesk Platform Services viewer. A translated building model, often from Revit, is loaded. You inspect and drive the viewer only through your tools; you cannot edit the model.

How to work
- For orientation use get_model_info, list_levels, or list_categories. Never guess level or category names.
- find_elements, search_text, and get_selection save a named element set (set-1, set-2, ...) and return a sample. Pass setId to any tool that takes ids instead of repeating dbIds. setId "selection" means what the user has selected right now. list_sets recalls the sets.
- Display changes stay until changed. The user can undo each one from the interface.
- run_query runs JavaScript over a copy of the property database in a sandbox with no page or network access, for counts, sums, and groupings the other tools cannot express. pdb offers leaves(), elements() ({dbId, name, category, level}), name(id), props(id) (visible properties, type properties merged), prop(id, name), find((id, pdb) => boolean), and attributes(). Return a small JSON value.
- take_screenshot shows you the current view as an image. Use it to check what the user sees.
- After open_view, levels and categories are rebuilt for the new view; set ids stay valid within the same file.

Units
- Positions, section offsets, camera coordinates, and measure_bbox lengths are viewer coordinates in model units (get_model_info names the unit; Revit models are usually feet). measure_bbox also reports metres.
- Property values keep the units they were authored in, which can differ from model units.

Answering
- Keep answers short: lead with the answer, then the counts or names behind it. Refer to set ids instead of listing dbIds.
- Before you hide, isolate, colour, or section a large part of the model, say in one sentence what you are about to change.
- If a tool fails, say what failed. Never invent results.`

export function createViewerAgentTools(
  getViewer: () => ViewerAgentViewer | null,
  options: ViewerAgentToolsOptions = {},
): ViewerAgentTools {
  const math = options.math ?? defaultMath
  const now = options.now ?? Date.now
  const sets = new ElementSetStore(50, now)
  const colors = new ColorLedger()
  const sandbox = new QuerySandbox(options.createQueryWorker)
  const savedStates = new Map<string, ViewerSnapshot>()

  let trackedModel: ViewerAgentModel | null = null
  let trackedDocument: ViewerAgentDocument | null = null
  let modelKey = 0
  let indexPromise: Promise<ElementIndex> | null = null
  let snapshotPromise: Promise<PropertySnapshot> | null = null
  let undoSequence = 0

  const repaint = (viewer: ViewerAgentViewer, model: ViewerAgentModel) => {
    viewer.clearThemingColors(model)
    for (const [id, hex] of colors.entries()) {
      const { r, g, b } = parseHexColor(hex)
      viewer.setThemingColor(id, math.vector4(r, g, b, 1), model, true)
    }
    viewer.impl.invalidate(true, true, true)
  }

  const restoreSnapshot = (
    viewer: ViewerAgentViewer,
    snapshot: ViewerSnapshot,
    filter?: ViewerStateFilter,
  ) => {
    if (!viewer.model) return
    const mode = hideOthersOf(viewer)
    if (mode?.getHideOthersState().active && !snapshot.hideOthers) mode.setHideOthers(false)
    viewer.restoreState(snapshot.viewerState, filter)
    if (mode && snapshot.hideOthers) mode.setHideOthers(true, snapshot.hideOthers)
    colors.restore(snapshot.colors)
    repaint(viewer, viewer.model)
  }

  const undo = new UndoStack((snapshot) => {
    const viewer = getViewer()
    if (viewer) {
      restoreSnapshot(viewer, snapshot, snapshot.restoreCamera ? undefined : KEEP_CAMERA)
    }
  })

  const sync = (viewer: ViewerAgentViewer) => {
    if (viewer.model === trackedModel) return
    const nextDocument = documentOf(viewer.model)
    if (trackedDocument !== null && nextDocument !== trackedDocument) sets.clear()
    trackedModel = viewer.model
    trackedDocument = nextDocument
    modelKey += 1
    indexPromise = null
    snapshotPromise = null
    savedStates.clear()
    colors.remove()
    undo.clear()
  }

  const requireModel = (viewer: ViewerAgentViewer): ViewerAgentModel => {
    if (!viewer.model) throw new Error('no model is loaded in the viewer yet')
    return viewer.model
  }

  const kit: ViewerToolKit = {
    math,
    sets,
    colors,
    savedStates,
    resultLimit: options.resultTextLimit ?? RESULT_TEXT_LIMIT,
    queryTimeoutMs: options.queryTimeoutMs ?? 10_000,
    now,
    sync,
    requireModel,
    getIndex(viewer) {
      const model = requireModel(viewer)
      if (!indexPromise) {
        const pending = buildElementIndex(model, math)
        indexPromise = pending
        pending.catch(() => {
          if (indexPromise === pending) indexPromise = null
        })
      }
      return indexPromise
    },
    getSnapshot(model) {
      if (!snapshotPromise) {
        const pending = loadPropertySnapshot(model, options.queryMaxPairs ?? 6_000_000)
        snapshotPromise = pending
        pending.catch(() => {
          if (snapshotPromise === pending) snapshotPromise = null
        })
      }
      return snapshotPromise
    },
    resolveTargets(args, viewer, idsKey = 'ids', setKey = 'setId') {
      const ids = args.numbers(idsKey) ?? []
      const setId = args.string(setKey)
      const parts: string[] = []
      const dbIds = [...ids]
      if (ids.length > 0) parts.push(plural(ids.length, 'id'))
      if (setId === 'selection') {
        const selection = viewer.getSelection()
        if (selection.length === 0) throw new ToolInputError('nothing is selected in the viewer')
        dbIds.push(...selection)
        parts.push('the selection')
      } else if (setId) {
        const set = sets.get(setId)
        if (!set) {
          const known = sets
            .list()
            .map((item) => item.id)
            .join(', ')
          throw new ToolInputError(`unknown set ${setId} (sets: ${known || 'none yet'})`)
        }
        dbIds.push(...set.dbIds)
        parts.push(`${set.id} (${set.label})`)
      }
      if (dbIds.length === 0) throw new ToolInputError(`give ${idsKey} or ${setKey}`)
      return { dbIds: [...new Set(dbIds)], source: parts.join(' and ') }
    },
    repaint,
    takeSnapshot(viewer) {
      const mode = hideOthersOf(viewer)?.getHideOthersState()
      return {
        viewerState: viewer.getState(),
        colors: colors.snapshot(),
        hideOthers: mode?.active ? [...mode.ids] : null,
      }
    },
    restoreSnapshot,
    runQuery: (request) => sandbox.run({ ...request, key: modelKey }),
  }

  const define = (spec: ViewerToolSpec): ViewerAgentTool => {
    const inputSchema: AgentToolSchema = {
      type: 'object',
      properties: spec.properties ?? {},
      additionalProperties: false,
    }
    if (spec.required) inputSchema.required = spec.required
    return {
      name: spec.name,
      description: spec.description,
      inputSchema,
      mutates: spec.mutates,
      async execute(input, context) {
        const args = validateToolInput(inputSchema, input)
        throwIfAborted(context.signal)
        const viewer = getViewer()
        if (!viewer) throw new Error('the viewer is not ready yet')
        sync(viewer)
        const before = spec.mutates ? kit.takeSnapshot(viewer) : null
        const { skipUndo, ...outcome } = await spec.run(args, viewer, context.signal)
        const result: AgentToolResult = {
          ...outcome,
          text: truncateResultText(outcome.text, kit.resultLimit),
        }
        if (result.text !== outcome.text) result.partial = true
        if (before && !skipUndo) {
          const { movesCamera } = spec
          before.restoreCamera =
            typeof movesCamera === 'function' ? movesCamera(args) : (movesCamera ?? false)
          undoSequence += 1
          const undoId = context.actionId ?? `undo-${undoSequence}`
          undo.push({ id: undoId, label: outcome.label, createdAt: now() }, before)
          result.undoable = true
          result.undoId = undoId
        }
        return result
      },
    }
  }

  const describeSelection = async (dbIds?: readonly number[]): Promise<AgentSelectionContext> => {
    const viewer = getViewer()
    const ids = [...(dbIds ?? viewer?.getSelection() ?? [])]
    if (!viewer || ids.length === 0) return { dbIds: [], summary: 'Nothing selected' }
    sync(viewer)
    const index = await kit.getIndex(viewer).catch(() => null)
    const rows = ids.map((id) => index?.byId.get(id))
    if (ids.length === 1) {
      const row = rows[0]
      if (!row) return { dbIds: ids, summary: `Element ${ids[0]}` }
      return { dbIds: ids, summary: row.category ? `${row.name} · ${row.category}` : row.name }
    }
    const counts = new Map<string, number>()
    for (const row of rows) {
      if (row?.category) counts.set(row.category, (counts.get(row.category) ?? 0) + 1)
    }
    const top = [...counts]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 2)
      .map(([category, count]) => `${count} ${category}`)
    return { dbIds: ids, summary: top.join(', ') }
  }

  return {
    tools: [...inspectionTools(kit), ...displayTools(kit)].map(define),
    sets,
    undo,
    colors,
    instructions: VIEWER_AGENT_INSTRUCTIONS,
    describeSelection,
    dispose: () => sandbox.dispose(),
  }
}

import type {
  AgentToolResult,
  AgentToolSchema,
  AgentToolSchemaProperty,
  JsonValue,
} from '@/lib/agent-types'
import type { QueryRunResult } from '@/lib/viewer-agent-query'
import type {
  ColorLedger,
  ElementIndex,
  ElementRow,
  ElementSetStore,
  ViewerSnapshot,
} from '@/lib/viewer-agent-state'
import {
  APS_HIDE_OTHERS_EXTENSION_ID,
  type APSHideOthersController,
  isAPSHideOthersController,
  type Vec3,
} from '@/lib/viewer-types'

type PropertyResult = Autodesk.Viewing.PropertyResult

export interface ViewerAgentTree {
  getRootId(): number
  getChildCount(dbId: number): number
  getNodeName(dbId: number): string
  enumNodeChildren(dbId: number, callback: (dbId: number) => void, recursive?: boolean): void
  enumNodeFragments(dbId: number, callback: (fragId: number) => void, recursive?: boolean): void
}

export interface ViewerAgentDocumentNode {
  guid(): string
  name(): string
  is2D(): boolean
  is3D(): boolean
  getDocument(): ViewerAgentDocument
}

export interface ViewerAgentDocument {
  getRoot(): { search(props: { type?: string; role?: string }): ViewerAgentDocumentNode[] }
  downloadAecModelData(): Promise<AecModelData | null>
}

/** The slice of a document's AEC model data the index reads; parsed before use. */
export interface AecModelData {
  levels?: unknown
}

export interface ViewerAgentModel {
  getObjectTree(
    onSuccess: (tree: ViewerAgentTree) => void,
    onError?: (error: unknown) => void,
  ): void
  getBulkProperties2(
    dbIds: number[],
    options: { propFilter?: string[] },
    onSuccess: (results: PropertyResult[]) => void,
    onError: (error: unknown) => void,
  ): void
  getFragmentList(): { getWorldBounds(fragId: number, box: THREE.Box3): void }
  getBoundingBox(): { min: Vec3; max: Vec3 }
  getUnitString(): string
  getUnitScale(): number
  getDocumentNode(): ViewerAgentDocumentNode | null
  getPropertyDb(): {
    executeUserFunction(
      userFunction: (pdb: LmvPropertyDatabase, userData: number) => PropertySnapshotExport,
      userData: number,
    ): Promise<PropertySnapshotExport>
  }
  is2d(): boolean
  isLoadDone(): boolean
  isObjectTreeCreated(): boolean
}

export interface ViewerAgentNavigation {
  getPosition(): Vec3
  getTarget(): Vec3
  getCameraUpVector(): Vec3
  setView(position: THREE.Vector3, target: THREE.Vector3): void
  setCameraUpVector(up: THREE.Vector3): void
  setPivotPoint(pivot: THREE.Vector3): void
}

export interface ViewerAgentState {
  [key: string]: JsonValue
}

/** The members of `APSViewer3D` the tool catalog drives; a real viewer satisfies it. */
export interface ViewerAgentViewer {
  model: ViewerAgentModel | null
  navigation: ViewerAgentNavigation
  container: { clientWidth: number; clientHeight: number }
  impl: { invalidate(needsClear: boolean, needsRender?: boolean, overlayDirty?: boolean): void }
  getSelection(): number[]
  select(dbIds: number[] | number): void
  clearSelection(): void
  isolate(dbIds?: number[] | number): void
  setGhosting(value: boolean): void
  getExtension(id: string): object | null
  hide(dbIds: number[] | number): void
  showAll(): void
  fitToView(dbIds?: number[] | null, model?: ViewerAgentModel, immediate?: boolean): void
  setThemingColor(
    dbId: number,
    color: THREE.Vector4,
    model?: ViewerAgentModel,
    recursive?: boolean,
  ): void
  clearThemingColors(model: ViewerAgentModel): void
  setCutPlanes(planes: THREE.Vector4[]): void
  getState(): ViewerAgentState
  restoreState(state: ViewerAgentState, filter?: ViewerStateFilter, immediate?: boolean): boolean
  getScreenShot(width: number, height: number, callback: (url: string) => void): void
  search(
    text: string,
    onSuccess: (dbIds: number[]) => void,
    onError: (error: unknown) => void,
    attributeNames?: string[],
  ): void
  loadDocumentNode(
    document: ViewerAgentDocument,
    node: ViewerAgentDocumentNode,
    options?: { keepCurrentModels?: boolean },
  ): Promise<ViewerAgentModel>
}

/** Constructors for the viewer's bundled THREE, injectable so tests run without it. */
export interface ViewerMath {
  vector3(x: number, y: number, z: number): THREE.Vector3
  vector4(x: number, y: number, z: number, w: number): THREE.Vector4
  box3(): THREE.Box3
}

export interface LmvAttributeDefinition {
  name: string
  category: string
  displayName?: string
  flags?: number
}

/** The property database LMV hands `executeUserFunction`, inside its worker. */
export interface LmvPropertyDatabase {
  getObjectCount(): number
  enumAttributes(callback: (attrId: number, definition: LmvAttributeDefinition) => void): void
  enumObjectProperties(dbId: number, callback: (attrId: number, valueId: number) => void): void
  getAttrValue(attrId: number, valueId: number): string | number | boolean | null
}

export type PropertyValue = string | number | boolean | null

export interface PropertySnapshotAttribute {
  name: string
  category: string
  displayName: string
  hidden: boolean
}

/** The whole property database as flat tables: object `id` owns pairs `offsets[id]` up to
 * `offsets[id + 1]`, each pair an attribute index and a value index. */
export interface PropertySnapshot {
  objectCount: number
  attributes: PropertySnapshotAttribute[]
  offsets: Int32Array
  pairs: Int32Array
  values: PropertyValue[]
}

export type PropertySnapshotExport =
  | ({ ok: true } & PropertySnapshot)
  | { ok: false; pairs: number; limit: number }

export const RESULT_TEXT_LIMIT = 60_000

export class ToolInputError extends Error {
  override name = 'ToolInputError'
}

type ToolArgValue = string | number | boolean | string[] | number[]

export class ToolArgs {
  private readonly values: ReadonlyMap<string, ToolArgValue>

  constructor(values: ReadonlyMap<string, ToolArgValue>) {
    this.values = values
  }

  has(name: string): boolean {
    return this.values.has(name)
  }

  string(name: string): string | undefined {
    const value = this.values.get(name)
    return typeof value === 'string' ? value : undefined
  }

  number(name: string): number | undefined {
    const value = this.values.get(name)
    return typeof value === 'number' ? value : undefined
  }

  boolean(name: string): boolean | undefined {
    const value = this.values.get(name)
    return typeof value === 'boolean' ? value : undefined
  }

  numbers(name: string): number[] | undefined {
    const value = this.values.get(name)
    if (!Array.isArray(value)) return undefined
    return value.filter((item): item is number => typeof item === 'number')
  }

  strings(name: string): string[] | undefined {
    const value = this.values.get(name)
    if (!Array.isArray(value)) return undefined
    return value.filter((item): item is string => typeof item === 'string')
  }
}

type ScalarCheck = { ok: true; value: string | number | boolean } | { ok: false; problem: string }

function checkScalar(name: string, value: unknown, property: AgentToolSchemaProperty): ScalarCheck {
  const fail = (problem: string): ScalarCheck => ({ ok: false, problem: `${name} ${problem}` })
  switch (property.type) {
    case 'string':
      if (typeof value !== 'string') return fail('must be a string')
      if (property.maxLength !== undefined && value.length > property.maxLength) {
        return fail(`must be at most ${property.maxLength} characters`)
      }
      if (property.enum && !property.enum.includes(value)) {
        return fail(`must be one of ${property.enum.join(', ')}`)
      }
      return { ok: true, value }
    case 'number':
    case 'integer':
      if (typeof value !== 'number' || !Number.isFinite(value)) return fail('must be a number')
      if (property.type === 'integer' && !Number.isInteger(value)) return fail('must be an integer')
      if (property.minimum !== undefined && value < property.minimum) {
        return fail(`must be at least ${property.minimum}`)
      }
      if (property.maximum !== undefined && value > property.maximum) {
        return fail(`must be at most ${property.maximum}`)
      }
      return { ok: true, value }
    case 'boolean':
      return typeof value === 'boolean' ? { ok: true, value } : fail('must be true or false')
    case 'array':
      return fail('must be an array')
  }
}

/** Checks model-written input against a tool's schema; throws one message naming every problem. */
export function validateToolInput(schema: AgentToolSchema, input: unknown): ToolArgs {
  const raw = input === undefined || input === null ? {} : input
  if (typeof raw !== 'object' || Array.isArray(raw)) {
    throw new ToolInputError('arguments must be a JSON object')
  }
  const entries: [string, unknown][] = Object.entries(raw)
  const problems: string[] = []
  const values = new Map<string, ToolArgValue>()
  for (const [name, value] of entries) {
    const property = schema.properties[name]
    if (!property) {
      problems.push(
        `unknown argument ${name} (allowed: ${Object.keys(schema.properties).join(', ') || 'none'})`,
      )
      continue
    }
    if (value === null || value === undefined) continue
    if (property.type === 'array') {
      if (!Array.isArray(value)) {
        problems.push(`${name} must be an array`)
        continue
      }
      const items: unknown[] = value
      if (property.maxItems !== undefined && items.length > property.maxItems) {
        problems.push(`${name} must have at most ${property.maxItems} items`)
        continue
      }
      if (property.items.type === 'string') {
        if (!items.every((item) => typeof item === 'string')) {
          problems.push(`${name} must be an array of strings`)
          continue
        }
        values.set(
          name,
          items.filter((item): item is string => typeof item === 'string'),
        )
      } else {
        const numbers = items.filter(
          (item): item is number => typeof item === 'number' && Number.isFinite(item),
        )
        const integral = property.items.type === 'integer'
        if (numbers.length !== items.length || (integral && !numbers.every(Number.isInteger))) {
          problems.push(`${name} must be an array of ${integral ? 'integers' : 'numbers'}`)
          continue
        }
        values.set(name, numbers)
      }
      continue
    }
    const checked = checkScalar(name, value, property)
    if (checked.ok) values.set(name, checked.value)
    else problems.push(checked.problem)
  }
  for (const name of schema.required ?? []) {
    if (!values.has(name) && !problems.some((problem) => problem.startsWith(`${name} `))) {
      problems.push(`${name} is required`)
    }
  }
  if (problems.length > 0) throw new ToolInputError(problems.join('; '))
  return new ToolArgs(values)
}

export interface HexColor {
  hex: string
  r: number
  g: number
  b: number
}

/** Accepts `#rgb`, `rgb`, `#rrggbb`, or `rrggbb`; channels come back as 0–1 fractions. */
export function parseHexColor(value: string): HexColor {
  let hex = value.trim().replace(/^#/, '').toLowerCase()
  if (/^[0-9a-f]{3}$/.test(hex)) {
    hex = hex
      .split('')
      .map((digit) => digit + digit)
      .join('')
  }
  if (!/^[0-9a-f]{6}$/.test(hex)) {
    throw new ToolInputError(`not a colour: ${value} (use a hex value such as #e5484d)`)
  }
  return {
    hex: `#${hex}`,
    r: Number.parseInt(hex.slice(0, 2), 16) / 255,
    g: Number.parseInt(hex.slice(2, 4), 16) / 255,
    b: Number.parseInt(hex.slice(4, 6), 16) / 255,
  }
}

export function truncateResultText(text: string, limit: number = RESULT_TEXT_LIMIT): string {
  if (text.length <= limit) return text
  const note = `\n[truncated: ${text.length} characters, showing ${limit}. Narrow it with limit or filters.]`
  return text.slice(0, Math.max(0, limit - note.length)) + note
}

export function formatSetId(sequence: number): string {
  return `set-${sequence}`
}

export interface Box {
  min: Vec3
  max: Vec3
}

export function isValidBox(box: Box): boolean {
  const { min, max } = box
  return (
    [min.x, min.y, min.z, max.x, max.y, max.z].every(Number.isFinite) &&
    min.x <= max.x &&
    min.y <= max.y &&
    min.z <= max.z
  )
}

export function unionBoxes(boxes: readonly Box[]): Box | null {
  let result: Box | null = null
  for (const box of boxes) {
    if (!isValidBox(box)) continue
    if (!result) {
      result = { min: { ...box.min }, max: { ...box.max } }
      continue
    }
    result = {
      min: {
        x: Math.min(result.min.x, box.min.x),
        y: Math.min(result.min.y, box.min.y),
        z: Math.min(result.min.z, box.min.z),
      },
      max: {
        x: Math.max(result.max.x, box.max.x),
        y: Math.max(result.max.y, box.max.y),
        z: Math.max(result.max.z, box.max.z),
      },
    }
  }
  return result
}

export function boxCenter(box: Box): Vec3 {
  return {
    x: (box.min.x + box.max.x) / 2,
    y: (box.min.y + box.max.y) / 2,
    z: (box.min.z + box.max.z) / 2,
  }
}

export function boxSize(box: Box): Vec3 {
  return { x: box.max.x - box.min.x, y: box.max.y - box.min.y, z: box.max.z - box.min.z }
}

export function distance(a: Vec3, b: Vec3): number {
  return Math.hypot(b.x - a.x, b.y - a.y, b.z - a.z)
}

/** Shortest distance between two axis-aligned boxes; 0 when they touch or overlap. */
export function boxGap(a: Box, b: Box): number {
  const axis = (aMin: number, aMax: number, bMin: number, bMax: number) =>
    Math.max(0, bMin - aMax, aMin - bMax)
  return Math.hypot(
    axis(a.min.x, a.max.x, b.min.x, b.max.x),
    axis(a.min.y, a.max.y, b.min.y, b.max.y),
    axis(a.min.z, a.max.z, b.min.z, b.max.z),
  )
}

export function describeError(error: unknown): string {
  if (error instanceof Error) return error.message
  if (typeof error === 'string') return error
  try {
    return JSON.stringify(error) ?? String(error)
  } catch {
    return String(error)
  }
}

export function roundNumber(value: number, digits = 3): number {
  const factor = 10 ** digits
  return Math.round(value * factor) / factor
}

export const SCREENSHOT_MAX_EDGE = 1024

/** LMV files Category under `__category__`; every other `__` category is tree bookkeeping. */
export function isInternalCategory(category: string): boolean {
  return category.startsWith('__') && category !== '__category__'
}

/** The viewer's Hide others mode when `aps-viewer` registered it, else null. */
export function hideOthersOf(viewer: ViewerAgentViewer): APSHideOthersController | null {
  const extension = viewer.getExtension(APS_HIDE_OTHERS_EXTENSION_ID)
  return isAPSHideOthersController(extension) ? extension : null
}

export function documentOf(model: ViewerAgentModel | null): ViewerAgentDocument | null {
  try {
    return model?.getDocumentNode()?.getDocument() ?? null
  } catch {
    return null
  }
}

export function json(value: JsonValue): string {
  return JSON.stringify(value)
}

export function plural(count: number, noun: string, many = `${noun}s`): string {
  return `${count} ${count === 1 ? noun : many}`
}

export function roundVec(vector: Vec3): JsonValue {
  return { x: roundNumber(vector.x), y: roundNumber(vector.y), z: roundNumber(vector.z) }
}

export function roundBox(box: Box): JsonValue {
  return { min: roundVec(box.min), max: roundVec(box.max) }
}

export function elementJson(row: ElementRow): JsonValue {
  return { id: row.dbId, name: row.name, category: row.category, level: row.level }
}

export function throwIfAborted(signal: AbortSignal): void {
  if (signal.aborted) throw new Error('cancelled')
}

