function toBase64(bytes: Uint8Array): string {
  let binary = ''
  for (let start = 0; start < bytes.length; start += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(start, start + 0x8000))
  }
  return btoa(binary)
}

/** The translated source file, e.g. `Tower.rvt`: the manifest's first viewable folder. */
export function sourceFileName(node: ViewerAgentDocumentNode | null): string | null {
  try {
    const viewable = node?.getDocument().getRoot().search({ type: 'folder', role: 'viewable' })[0]
    return viewable?.name() || null
  } catch {
    return null
  }
}

function formatValue(property: Autodesk.Viewing.Property): string {
  const unit = property.units
    ? ` ${property.units.replace(/^autodesk\.unit\.unit:/, '').replace(/-[\d.]+$/, '')}`
    : ''
  const value =
    typeof property.displayValue === 'number'
      ? String(roundNumber(property.displayValue, 4))
      : String(property.displayValue)
  return `${value}${unit}`
}

function screenshotBlob(viewer: ViewerAgentViewer, width: number, height: number): Promise<Blob> {
  return new Promise<Blob>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('the screenshot timed out')), 20_000)
    viewer.getScreenShot(width, height, (url) => {
      clearTimeout(timer)
      fetch(url)
        .then((response) => response.blob())
        .then(resolve, reject)
        .finally(() => {
          if (url.startsWith('blob:')) URL.revokeObjectURL(url)
        })
    })
  })
}

/** PNG screenshots run to hundreds of kilobytes and every image stays in the conversation
 * checkpoint, which libfx caps at 4 MiB; JPEG keeps a view legible at a fraction of that. */
async function compressScreenshot(blob: Blob): Promise<Blob> {
  if (typeof createImageBitmap !== 'function' || typeof OffscreenCanvas !== 'function') return blob
  try {
    const bitmap = await createImageBitmap(blob)
    const canvas = new OffscreenCanvas(bitmap.width, bitmap.height)
    const context = canvas.getContext('2d')
    if (!context) return blob
    context.fillStyle = '#ffffff'
    context.fillRect(0, 0, bitmap.width, bitmap.height)
    context.drawImage(bitmap, 0, 0)
    bitmap.close()
    const jpeg = await canvas.convertToBlob({ type: 'image/jpeg', quality: 0.8 })
    return jpeg.size < blob.size ? jpeg : blob
  } catch {
    return blob
  }
}

export function inspectionTools(kit: ViewerToolKit): ViewerToolSpec[] {
  return [
    {
      name: 'get_model_info',
      description:
        'Source file name, loaded view, units, element count, level and category counts, bounding box, and the current selection size.',
      mutates: false,
      async run(_args, viewer) {
        const model = kit.requireModel(viewer)
        const index = await kit.getIndex(viewer)
        const node = model.getDocumentNode()
        const box = model.getBoundingBox()
        const units = model.getUnitString() || 'unknown'
        return {
          text: json({
            file: sourceFileName(node),
            view: node?.name() ?? null,
            is2d: model.is2d(),
            units,
            metresPerUnit: roundNumber(model.getUnitScale(), 6),
            elements: index.elements.length,
            levels: index.levels.length,
            categories: index.categories.length,
            boundingBox: roundBox(box),
            selected: viewer.getSelection().length,
            sets: kit.sets.list().length,
          }),
          label: 'Read the model summary',
          detail: `${plural(index.elements.length, 'element')} · ${units}`,
        }
      },
    },
    {
      name: 'list_levels',
      description:
        'Every level with its element count, authored elevation when known, and the viewer z range of its elements.',
      mutates: false,
      async run(_args, viewer) {
        const index = await kit.getIndex(viewer)
        return {
          text: json({
            levels: index.levels.map((level) => ({
              name: level.name,
              elements: level.count,
              elevation: level.elevation === null ? null : roundNumber(level.elevation),
              zMin: level.zMin === null ? null : roundNumber(level.zMin),
              zMax: level.zMax === null ? null : roundNumber(level.zMax),
            })),
          }),
          label: `Listed ${plural(index.levels.length, 'level')}`,
        }
      },
    },
    {
      name: 'list_categories',
      description: 'Element categories (Walls, Doors, ...) with counts, largest first.',
      properties: { limit: limitProperty(100, 500) },
      mutates: false,
      async run(args, viewer) {
        const index = await kit.getIndex(viewer)
        const limit = args.number('limit') ?? 100
        return {
          text: json({
            total: index.categories.length,
            categories: index.categories
              .slice(0, limit)
              .map((row) => ({ name: row.name, elements: row.count })),
          }),
          label: `Listed ${plural(Math.min(limit, index.categories.length), 'category', 'categories')}`,
        }
      },
    },
    {
      name: 'find_elements',
      description:
        'Find leaf elements matching every given filter (category, level, name, a property value). Exact names win over substrings. Saves all matches as a set and lists a sample.',
      properties: {
        category: { type: 'string', maxLength: 200 },
        level: { type: 'string', maxLength: 200 },
        name: { type: 'string', maxLength: 200, description: 'Substring of the element name.' },
        propertyName: { type: 'string', maxLength: 200 },
        propertyValue: {
          type: 'string',
          maxLength: 500,
          description: 'Requires propertyName; omit it to match any non-empty value.',
        },
        label: { type: 'string', maxLength: 80, description: 'A name for the saved set.' },
        limit: limitProperty(20, 500),
      },
      mutates: false,
      async run(args, viewer) {
        const category = args.string('category')
        const level = args.string('level')
        const name = args.string('name')
        const propertyName = args.string('propertyName')
        const propertyValue = args.string('propertyValue')
        if (!category && !level && !name && !propertyName) {
          throw new ToolInputError('give at least one of category, level, name, propertyName')
        }
        if (propertyValue !== undefined && !propertyName) {
          throw new ToolInputError('propertyValue needs propertyName')
        }
        const index = await kit.getIndex(viewer)
        let hits = filterElements(index.elements, { category, level, name })
        if (propertyName && hits.length > 0) {
          const wantedName = propertyName.toLocaleLowerCase()
          const wantedValue = propertyValue?.toLocaleLowerCase()
          const results = await bulkProperties(
            index.model,
            hits.map((row) => row.dbId),
            [propertyName],
          )
          const matched = new Set<number>()
          for (const result of results) {
            for (const property of result.properties) {
              if (property.displayName.toLocaleLowerCase() !== wantedName) continue
              const value = String(property.displayValue ?? '').toLocaleLowerCase()
              if (wantedValue === undefined ? value !== '' : value.includes(wantedValue)) {
                matched.add(result.dbId)
              }
            }
          }
          hits = hits.filter((row) => matched.has(row.dbId))
        }
        const description = [
          category ?? 'Elements',
          level ? `on ${level}` : '',
          name ? `named “${name}”` : '',
          propertyName ? `with ${propertyName}${propertyValue ? ` = ${propertyValue}` : ''}` : '',
        ]
          .filter(Boolean)
          .join(' ')
        if (hits.length === 0) {
          return {
            text: json({
              count: 0,
              hint: 'No matches. Check names with list_levels or list_categories.',
            }),
            label: `No ${description.toLocaleLowerCase()}`,
          }
        }
        const set = kit.sets.create(
          args.string('label') ?? description,
          hits.map((row) => row.dbId),
          'find_elements',
        )
        const limit = args.number('limit') ?? 20
        return {
          text: json({
            set: set.id,
            count: hits.length,
            shown: Math.min(limit, hits.length),
            elements: hits.slice(0, limit).map(elementJson),
          }),
          label: `Found ${plural(hits.length, 'element')}: ${description}`,
          detail: set.id,
          setId: set.id,
        }
      },
    },
    {
      name: 'search_text',
      description:
        'Full-text search across property values (optionally only in the named properties). Saves the matching leaf elements as a set.',
      properties: {
        text: { type: 'string', maxLength: 200 },
        propertyNames: { type: 'array', items: { type: 'string' }, maxItems: 20 },
        limit: limitProperty(20, 500),
      },
      required: ['text'],
      mutates: false,
      async run(args, viewer) {
        const text = args.string('text') ?? ''
        const index = await kit.getIndex(viewer)
        const names = args.strings('propertyNames')
        const raw = await new Promise<number[]>((resolve, reject) =>
          viewer.search(
            text,
            resolve,
            (error) => reject(new Error(`search failed: ${describeError(error)}`)),
            names,
          ),
        )
        const hits = [...new Set(raw)].filter((id) => index.byId.has(id))
        if (hits.length === 0) {
          return { text: json({ count: 0 }), label: `No matches for “${text}”` }
        }
        const set = kit.sets.create(`“${text}”`, hits, 'search_text')
        const limit = args.number('limit') ?? 20
        return {
          text: json({
            set: set.id,
            count: hits.length,
            shown: Math.min(limit, hits.length),
            elements: hits.slice(0, limit).flatMap((id) => {
              const row = index.byId.get(id)
              return row ? [elementJson(row)] : []
            }),
          }),
          label: `Found ${plural(hits.length, 'match', 'matches')} for “${text}”`,
          detail: set.id,
          setId: set.id,
        }
      },
    },
    {
      name: 'get_properties',
      description:
        'Properties of elements, optionally only the named ones. Lists the first `limit` elements.',
      properties: {
        ...targetProperties,
        names: { type: 'array', items: { type: 'string' }, maxItems: 50 },
        limit: limitProperty(10, 100),
      },
      mutates: false,
      async run(args, viewer) {
        const model = kit.requireModel(viewer)
        const { dbIds, source } = kit.resolveTargets(args, viewer)
        const names = args.strings('names')
        const limit = args.number('limit') ?? 10
        const wanted = names ? new Set(names.map((name) => name.toLocaleLowerCase())) : null
        const results = await bulkProperties(
          model,
          dbIds.slice(0, limit),
          names ? ['name', ...names] : undefined,
        )
        const elements = results.map((result) => {
          const properties: { [name: string]: JsonValue } = {}
          for (const property of result.properties) {
            const requested = wanted?.has(property.displayName.toLocaleLowerCase()) ?? false
            if (wanted && !requested) continue
            if (!wanted && (property.hidden || isInternalCategory(property.displayCategory))) {
              continue
            }
            if (property.displayValue === '' || property.displayValue === null) continue
            const key =
              property.displayName in properties
                ? `${property.displayName} (${property.displayCategory})`
                : property.displayName
            properties[key] = formatValue(property)
          }
          return { id: result.dbId, name: result.name ?? '', properties }
        })
        return {
          text: json({ count: dbIds.length, shown: elements.length, elements }),
          label: `Read properties of ${plural(elements.length, 'element')}`,
          detail: source,
        }
      },
    },
    {
      name: 'get_selection',
      description: 'What the user has selected in the viewer right now; saves it as a set.',
      mutates: false,
      async run(_args, viewer) {
        const selection = viewer.getSelection()
        if (selection.length === 0) {
          return {
            text: json({ count: 0, note: 'Nothing is selected.' }),
            label: 'Nothing selected',
          }
        }
        const index = await kit.getIndex(viewer)
        const set = kit.sets.create('Selection', selection, 'get_selection')
        return {
          text: json({
            set: set.id,
            count: selection.length,
            elements: selection.slice(0, 20).map((id) => {
              const row = index.byId.get(id)
              return row ? elementJson(row) : { id }
            }),
          }),
          label: `Read the selection (${plural(selection.length, 'element')})`,
          detail: set.id,
          setId: set.id,
        }
      },
    },
    {
      name: 'list_sets',
      description: 'The element sets saved so far, newest last.',
      mutates: false,
      async run() {
        const list = kit.sets.list()
        return {
          text: json({
            sets: list.map((set) => ({
              id: set.id,
              label: set.label,
              elements: set.dbIds.length,
              origin: set.origin,
            })),
          }),
          label: `Listed ${plural(list.length, 'set')}`,
        }
      },
    },
    {
      name: 'measure_bbox',
      description:
        'Combined bounding box of elements (size and centre). With toIds or toSetId, also the centre-to-centre distance and the box-to-box gap between the two groups.',
      properties: {
        ...targetProperties,
        toIds: { type: 'array', items: { type: 'integer' }, maxItems: 10_000 },
        toSetId: { type: 'string', maxLength: 64 },
      },
      mutates: false,
      async run(args, viewer) {
        const model = kit.requireModel(viewer)
        const index = await kit.getIndex(viewer)
        const unit = model.getUnitString() || 'model units'
        const scale = model.getUnitScale()
        const metres = (value: number) => (scale > 0 ? roundNumber(value * scale) : null)
        const first = kit.resolveTargets(args, viewer)
        const boxA = boundsOf(index, first.dbIds, kit.math)
        if (!boxA) throw new Error('those elements have no geometry to measure')
        const size = boxSize(boxA)
        const measured = {
          unit,
          size: roundVec(size),
          sizeMetres: { x: metres(size.x), y: metres(size.y), z: metres(size.z) },
          center: roundVec(boxCenter(boxA)),
          boundingBox: roundBox(boxA),
        }
        if (!args.has('toIds') && !args.has('toSetId')) {
          return {
            text: json(measured),
            label: `Measured ${plural(first.dbIds.length, 'element')}`,
            detail: first.source,
          }
        }
        const second = kit.resolveTargets(args, viewer, 'toIds', 'toSetId')
        const boxB = boundsOf(index, second.dbIds, kit.math)
        if (!boxB) throw new Error('the second group has no geometry to measure')
        const a = boxCenter(boxA)
        const b = boxCenter(boxB)
        const centres = distance(a, b)
        const gap = boxGap(boxA, boxB)
        return {
          text: json({
            ...measured,
            distance: roundNumber(centres),
            distanceMetres: metres(centres),
            delta: roundVec({ x: b.x - a.x, y: b.y - a.y, z: b.z - a.z }),
            gap: roundNumber(gap),
            gapMetres: metres(gap),
          }),
          label: `Measured ${roundNumber(centres, 2)} ${unit} between two groups`,
          detail: `${first.source} to ${second.source}`,
        }
      },
    },
    {
      name: 'take_screenshot',
      description: 'An image of the current view, attached so you can see it.',
      properties: {
        maxEdge: {
          type: 'integer',
          minimum: 256,
          maximum: SCREENSHOT_MAX_EDGE,
          description: `Longest side in pixels (default ${SCREENSHOT_MAX_EDGE}).`,
        },
      },
      mutates: false,
      async run(args, viewer) {
        const maxEdge = args.number('maxEdge') ?? SCREENSHOT_MAX_EDGE
        const { clientWidth, clientHeight } = viewer.container
        const longest = Math.max(clientWidth, clientHeight, 1)
        const scale = Math.min(1, maxEdge / longest)
        const width = Math.max(1, Math.round(clientWidth * scale))
        const height = Math.max(1, Math.round(clientHeight * scale))
        const blob = await compressScreenshot(await screenshotBlob(viewer, width, height))
        const bytes = new Uint8Array(await blob.arrayBuffer())
        const image: AgentImage = {
          mimeType: blob.type || 'image/png',
          base64: toBase64(bytes),
          width,
          height,
        }
        return {
          text: json({ width, height, bytes: bytes.length, note: 'The screenshot is attached.' }),
          label: 'Took a screenshot',
          detail: `${width} × ${height}`,
          image,
        }
      },
    },
    {
      name: 'run_query',
      description:
        'Evaluate JavaScript over a copy of the property database in a sandboxed worker (no page, no network), time-boxed. code is an expression, a function (pdb) => value, or a function body that returns. pdb: leaves(), elements(), name(id), props(id), prop(id, name), find((id, pdb) => boolean), attributes(). console.log output is returned too.',
      properties: {
        code: { type: 'string', maxLength: 20_000 },
        timeoutMs: { type: 'integer', minimum: 1000, maximum: 30_000 },
      },
      required: ['code'],
      mutates: false,
      async run(args, viewer, signal) {
        const model = kit.requireModel(viewer)
        const index = await kit.getIndex(viewer)
        const snapshot = await kit.getSnapshot(model)
        throwIfAborted(signal)
        const result = await kit.runQuery({
          snapshot,
          elements: index.elements,
          code: args.string('code') ?? '',
          timeoutMs: args.number('timeoutMs') ?? kit.queryTimeoutMs,
          maxChars: kit.resultLimit,
          signal,
        })
        const logs = result.logs.length > 0 ? `\nconsole:\n${result.logs.join('\n')}` : ''
        if (!result.ok) throw new Error(`${result.error}${logs}`)
        return {
          text: `${result.text}${logs}`,
          label: 'Ran a property query',
          detail: result.count === null ? undefined : plural(result.count, 'result'),
          partial: result.truncated,
        }
      },
    },
  ]
}

import {
  boxCenter,
  distance,
  documentOf,
  hideOthersOf,
  json,
  parseHexColor,
  plural,
  roundNumber,
  roundVec,
  ToolInputError,
  targetProperties,
  type ViewerAgentDocumentNode,
  type ViewerAgentViewer,
  type ViewerToolKit,
  type ViewerToolSpec,
} from '@/lib/viewer-agent-core'
import { boundsOf, type ElementIndex } from '@/lib/viewer-agent-state'

const CAMERA_PRESETS = new Map<string, [number, number, number]>([
  ['top', [0, 0, 1]],
  ['bottom', [0, 0, -1]],
  ['front', [0, -1, 0]],
  ['back', [0, 1, 0]],
  ['left', [-1, 0, 0]],
  ['right', [1, 0, 0]],
  ['iso', [1, -1, 1]],
])

const SECTION_DEFAULT_METERS = 1.2
const VIEW_LOAD_CEILING_MS = 30_000

function wait(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      signal.removeEventListener('abort', onAbort)
      resolve()
    }, ms)
    const onAbort = () => {
      clearTimeout(timer)
      reject(new Error('cancelled'))
    }
    signal.addEventListener('abort', onAbort, { once: true })
  })
}

function findLevel(index: ElementIndex, wanted: string): ElementIndex['levels'][number] {
  const target = wanted.trim().toLocaleLowerCase()
  const exact = index.levels.find((level) => level.name.toLocaleLowerCase() === target)
  if (exact) return exact
  const partial = index.levels.filter((level) => level.name.toLocaleLowerCase().includes(target))
  if (partial.length === 1) return partial[0]
  const names = index.levels.map((level) => level.name).join(', ')
  throw new ToolInputError(
    partial.length > 1
      ? `"${wanted}" matches several levels (${partial.map((level) => level.name).join(', ')})`
      : `unknown level "${wanted}" (levels: ${names || 'none found'})`,
  )
}

function viewables(viewer: ViewerAgentViewer, kit: ViewerToolKit): ViewerAgentDocumentNode[] {
  const doc = documentOf(kit.requireModel(viewer))
  if (!doc) throw new Error('the loaded model carries no document, so it has no views to list')
  return doc.getRoot().search({ type: 'geometry' })
}

function knownSet(kit: ViewerToolKit, setId: string | undefined): string | undefined {
  return setId && kit.sets.get(setId) ? setId : undefined
}

function currentGuid(viewer: ViewerAgentViewer): string | null {
  try {
    return viewer.model?.getDocumentNode()?.guid() ?? null
  } catch {
    return null
  }
}

export function displayTools(kit: ViewerToolKit): ViewerToolSpec[] {
  return [
    {
      name: 'select_elements',
      description: 'Select elements in the viewer. An empty ids array clears the selection.',
      properties: { ...targetProperties, fit: { type: 'boolean', description: 'Zoom to them.' } },
      mutates: true,
      movesCamera: (args) => args.boolean('fit') === true,
      async run(args, viewer) {
        if (args.numbers('ids')?.length === 0 && !args.string('setId')) {
          viewer.clearSelection()
          return { text: json({ selected: 0 }), label: 'Cleared the selection' }
        }
        const { dbIds, source } = kit.resolveTargets(args, viewer)
        viewer.select(dbIds)
        if (args.boolean('fit')) viewer.fitToView(dbIds)
        return {
          text: json({ selected: dbIds.length }),
          label: `Selected ${plural(dbIds.length, 'element')}`,
          detail: source,
          setId: knownSet(kit, args.string('setId')),
        }
      },
    },
    {
      name: 'isolate_elements',
      description:
        'Show only these elements; everything else is ghosted, or fully hidden with hideOthers (the toolbar Hide others mode, which then follows the user selection). show_all undoes either.',
      properties: {
        ...targetProperties,
        fit: { type: 'boolean', description: 'Zoom to them.' },
        hideOthers: { type: 'boolean', description: 'Hide everything else instead of ghosting.' },
      },
      mutates: true,
      movesCamera: (args) => args.boolean('fit') === true,
      async run(args, viewer) {
        const { dbIds, source } = kit.resolveTargets(args, viewer)
        const hideOthers = args.boolean('hideOthers') === true
        const mode = hideOthersOf(viewer)
        if (hideOthers && mode) {
          mode.setHideOthers(true, dbIds)
        } else if (hideOthers) {
          viewer.setGhosting(false)
          viewer.isolate(dbIds)
        } else {
          if (mode?.getHideOthersState().active) mode.setHideOthers(false)
          viewer.isolate(dbIds)
        }
        if (args.boolean('fit')) viewer.fitToView(dbIds)
        return {
          text: json({ isolated: dbIds.length, others: hideOthers ? 'hidden' : 'ghosted' }),
          label: `${hideOthers ? 'Hid all but' : 'Isolated'} ${plural(dbIds.length, 'element')}`,
          detail: source,
          setId: knownSet(kit, args.string('setId')),
        }
      },
    },
    {
      name: 'hide_elements',
      description: 'Hide elements. show_all brings them back.',
      properties: targetProperties,
      mutates: true,
      async run(args, viewer) {
        const { dbIds, source } = kit.resolveTargets(args, viewer)
        viewer.hide(dbIds)
        return {
          text: json({ hidden: dbIds.length }),
          label: `Hid ${plural(dbIds.length, 'element')}`,
          detail: source,
          setId: knownSet(kit, args.string('setId')),
        }
      },
    },
    {
      name: 'show_all',
      description: 'Clear isolation and show every hidden element.',
      mutates: true,
      async run(_args, viewer) {
        viewer.showAll()
        return { text: json({ shown: 'all' }), label: 'Showed every element' }
      },
    },
    {
      name: 'color_elements',
      description:
        'Paint elements with a colour (hex such as #e5484d). The label names the colour in the legend.',
      properties: {
        ...targetProperties,
        hex: { type: 'string', maxLength: 7 },
        label: { type: 'string', maxLength: 80 },
      },
      required: ['hex'],
      mutates: true,
      async run(args, viewer) {
        const model = kit.requireModel(viewer)
        const color = parseHexColor(args.string('hex') ?? '')
        const { dbIds, source } = kit.resolveTargets(args, viewer)
        const label = args.string('label') ?? source
        const vector = kit.math.vector4(color.r, color.g, color.b, 1)
        for (const id of dbIds) viewer.setThemingColor(id, vector, model, true)
        viewer.impl.invalidate(true, true, true)
        kit.colors.apply(dbIds, color.hex, label)
        return {
          text: json({
            colored: dbIds.length,
            hex: color.hex,
            legend: kit.colors.legend().map((entry) => ({ ...entry })),
          }),
          label: `Coloured ${plural(dbIds.length, 'element')}`,
          detail: label,
          color: color.hex,
          setId: knownSet(kit, args.string('setId')),
        }
      },
    },
    {
      name: 'clear_colors',
      description: 'Remove colours the agent applied, from the given elements or from all.',
      properties: targetProperties,
      mutates: true,
      async run(args, viewer) {
        const model = kit.requireModel(viewer)
        const scoped = args.has('ids') || args.has('setId')
        const removed = scoped
          ? kit.colors.remove(kit.resolveTargets(args, viewer).dbIds)
          : kit.colors.remove()
        kit.repaint(viewer, model)
        return {
          text: json({ cleared: removed, remaining: kit.colors.size }),
          label: scoped
            ? `Cleared colours from ${plural(removed, 'element')}`
            : 'Cleared all colours',
        }
      },
    },
    {
      name: 'fit_to_view',
      description: 'Zoom the camera to elements, or to the whole model when none are given.',
      properties: targetProperties,
      mutates: true,
      movesCamera: true,
      async run(args, viewer) {
        const scoped = args.has('ids') || args.has('setId')
        const targets = scoped ? kit.resolveTargets(args, viewer) : null
        viewer.fitToView(targets ? targets.dbIds : null)
        return {
          text: json({ fitted: targets ? targets.dbIds.length : 'model' }),
          label: targets
            ? `Zoomed to ${plural(targets.dbIds.length, 'element')}`
            : 'Zoomed to the model',
          detail: targets?.source,
        }
      },
    },
    {
      name: 'set_section',
      description:
        'One section plane: by level name (cuts offset model units above the level, default about 1.2 m) or by axis and position. Geometry beyond the plane is cut away.',
      properties: {
        level: { type: 'string', maxLength: 200 },
        offset: { type: 'number', description: 'Model units above the level.' },
        axis: { type: 'string', enum: ['x', 'y', 'z'] },
        position: { type: 'number', description: 'Viewer coordinate along the axis.' },
        flip: { type: 'boolean', description: 'Cut away the other side.' },
      },
      mutates: true,
      async run(args, viewer) {
        const model = kit.requireModel(viewer)
        if (model.is2d()) throw new ToolInputError('sections apply to 3D views only')
        const levelName = args.string('level')
        let axis = args.string('axis') ?? 'z'
        let position = args.number('position')
        let basis = 'position'
        if (levelName) {
          const level = findLevel(await kit.getIndex(viewer), levelName)
          const base = level.zMin ?? level.elevation
          if (base === null) throw new Error(`level ${level.name} has no elements to place a cut`)
          const scale = model.getUnitScale()
          const offset =
            args.number('offset') ??
            (scale > 0 ? SECTION_DEFAULT_METERS / scale : SECTION_DEFAULT_METERS)
          axis = 'z'
          position = base + offset
          basis = `${level.name} + ${roundNumber(offset)}`
        }
        if (position === undefined) throw new ToolInputError('give level, or axis and position')
        const sign = args.boolean('flip') ? -1 : 1
        const normal = { x: [1, 0, 0], y: [0, 1, 0], z: [0, 0, 1] }[axis] ?? [0, 0, 1]
        viewer.setCutPlanes([
          kit.math.vector4(normal[0] * sign, normal[1] * sign, normal[2] * sign, -position * sign),
        ])
        return {
          text: json({ axis, position: roundNumber(position), basis, flipped: sign === -1 }),
          label: levelName
            ? `Sectioned at ${basis}`
            : `Sectioned ${axis} at ${roundNumber(position)}`,
        }
      },
    },
    {
      name: 'clear_section',
      description: 'Remove the section plane.',
      mutates: true,
      async run(_args, viewer) {
        viewer.setCutPlanes([])
        return { text: json({ section: null }), label: 'Removed the section' }
      },
    },
    {
      name: 'set_camera',
      description:
        'Orient the camera to a preset view of the model, or look at elements from the current direction. Both together orient, then frame the elements.',
      properties: {
        preset: { type: 'string', enum: [...CAMERA_PRESETS.keys()] },
        ...targetProperties,
      },
      mutates: true,
      movesCamera: true,
      async run(args, viewer) {
        const model = kit.requireModel(viewer)
        const preset = args.string('preset')
        const scoped = args.has('ids') || args.has('setId')
        if (!preset && !scoped) throw new ToolInputError('give preset, or ids or setId to look at')
        const targets = scoped ? kit.resolveTargets(args, viewer) : null
        const nav = viewer.navigation
        if (model.is2d()) {
          if (preset) throw new ToolInputError('camera presets apply to 3D views only')
        } else if (preset) {
          const box = model.getBoundingBox()
          const center = boxCenter(box)
          const [dx, dy, dz] = CAMERA_PRESETS.get(preset) ?? [1, -1, 1]
          const length = Math.hypot(dx, dy, dz)
          const reach = Math.max(distance(box.min, box.max), 1)
          const up = preset === 'top' || preset === 'bottom' ? [0, 1, 0] : [0, 0, 1]
          nav.setView(
            kit.math.vector3(
              center.x + (dx / length) * reach,
              center.y + (dy / length) * reach,
              center.z + (dz / length) * reach,
            ),
            kit.math.vector3(center.x, center.y, center.z),
          )
          nav.setCameraUpVector(kit.math.vector3(up[0], up[1], up[2]))
        } else if (targets) {
          const box = boundsOf(await kit.getIndex(viewer), targets.dbIds, kit.math)
          if (box) {
            const center = boxCenter(box)
            const position = nav.getPosition()
            const target = nav.getTarget()
            nav.setView(
              kit.math.vector3(
                center.x + position.x - target.x,
                center.y + position.y - target.y,
                center.z + position.z - target.z,
              ),
              kit.math.vector3(center.x, center.y, center.z),
            )
            nav.setPivotPoint(kit.math.vector3(center.x, center.y, center.z))
          }
        }
        viewer.fitToView(targets ? targets.dbIds : null, model, true)
        return {
          text: json({
            preset: preset ?? null,
            framed: targets ? targets.dbIds.length : 'model',
            position: roundVec(nav.getPosition()),
            target: roundVec(nav.getTarget()),
          }),
          label: preset
            ? `Camera to ${preset}${targets ? `, framing ${plural(targets.dbIds.length, 'element')}` : ''}`
            : `Looked at ${plural(targets?.dbIds.length ?? 0, 'element')}`,
          detail: targets?.source,
        }
      },
    },
    {
      name: 'list_views',
      description: 'Every 3D view and 2D sheet in the file, with the loaded one marked.',
      mutates: false,
      async run(_args, viewer) {
        const nodes = viewables(viewer, kit)
        const current = currentGuid(viewer)
        return {
          text: json({
            views: nodes.map((node, position) => ({
              index: position + 1,
              name: node.name(),
              kind: node.is2D() ? '2d' : '3d',
              guid: node.guid(),
              loaded: node.guid() === current,
            })),
          }),
          label: `Listed ${plural(nodes.length, 'view')}`,
        }
      },
    },
    {
      name: 'open_view',
      description:
        'Switch to another view or sheet by index, guid, or name from list_views. Waits for it to load; display changes and undo history reset.',
      properties: { view: { type: 'string', maxLength: 200 } },
      required: ['view'],
      mutates: true,
      async run(args, viewer, signal) {
        const wanted = (args.string('view') ?? '').trim()
        const nodes = viewables(viewer, kit)
        const position = Number(wanted)
        const lower = wanted.toLocaleLowerCase()
        let node =
          (Number.isInteger(position) && position >= 1 ? nodes[position - 1] : undefined) ??
          nodes.find((item) => item.guid() === wanted) ??
          nodes.find((item) => item.name().toLocaleLowerCase() === lower)
        if (!node) {
          const partial = nodes.filter((item) => item.name().toLocaleLowerCase().includes(lower))
          if (partial.length > 1) {
            throw new ToolInputError(
              `"${wanted}" matches ${partial.length} views; use the index from list_views`,
            )
          }
          node = partial[0]
        }
        if (!node) throw new ToolInputError(`no view "${wanted}"; run list_views`)
        const label = `${node.is2D() ? 'sheet' : 'view'} “${node.name()}”`
        if (node.guid() === currentGuid(viewer)) {
          return {
            text: json({ loaded: node.name(), changed: false }),
            label: `${label} is already open`,
            skipUndo: true,
          }
        }
        const started = kit.now()
        const model = await viewer.loadDocumentNode(node.getDocument(), node, {
          keepCurrentModels: false,
        })
        while (!(model.isLoadDone() && model.isObjectTreeCreated())) {
          if (kit.now() - started > VIEW_LOAD_CEILING_MS) {
            return {
              text: json({
                loaded: node.name(),
                ready: false,
                note: 'Still loading; try again shortly.',
              }),
              label: `Opening ${label}`,
              partial: true,
              skipUndo: true,
            }
          }
          await wait(100, signal)
        }
        kit.sync(viewer)
        return {
          text: json({ loaded: node.name(), kind: node.is2D() ? '2d' : '3d', changed: true }),
          label: `Opened ${label}`,
          skipUndo: true,
        }
      },
    },
    {
      name: 'save_view_state',
      description: 'Save the camera, visibility, section, selection, and colours under a name.',
      properties: { name: { type: 'string', maxLength: 80 } },
      required: ['name'],
      mutates: false,
      async run(args, viewer) {
        const name = args.string('name') ?? ''
        kit.savedStates.delete(name)
        kit.savedStates.set(name, kit.takeSnapshot(viewer))
        for (const key of [...kit.savedStates.keys()].slice(
          0,
          Math.max(0, kit.savedStates.size - 20),
        )) {
          kit.savedStates.delete(key)
        }
        return { text: json({ saved: name }), label: `Saved the view as “${name}”` }
      },
    },
    {
      name: 'restore_view_state',
      description: 'Return to a view saved with save_view_state.',
      properties: { name: { type: 'string', maxLength: 80 } },
      required: ['name'],
      mutates: true,
      movesCamera: true,
      async run(args, viewer) {
        const name = args.string('name') ?? ''
        const saved = kit.savedStates.get(name)
        if (!saved) {
          const names = [...kit.savedStates.keys()].join(', ')
          throw new ToolInputError(`no saved view "${name}" (saved: ${names || 'none'})`)
        }
        kit.requireModel(viewer)
        kit.restoreSnapshot(viewer, saved)
        return { text: json({ restored: name }), label: `Restored the view “${name}”` }
      },
    },
  ]
}

import type {
  LmvPropertyDatabase,
  PropertySnapshot,
  PropertySnapshotAttribute,
  PropertySnapshotExport,
  PropertyValue,
  ViewerAgentModel,
} from '@/lib/viewer-agent-core'
import type { ElementRow } from '@/lib/viewer-agent-state'

// Runs inside LMV's property worker, which receives it as source text: it must stay
// self-contained, with no imports and no references outside its own body.
export const exportPropertySnapshot = (
  pdb: LmvPropertyDatabase,
  maxPairs: number,
): PropertySnapshotExport => {
  const objectCount = pdb.getObjectCount()
  const offsets = new Int32Array(objectCount + 1)
  const pairList: number[] = []
  const values: PropertyValue[] = []
  const valueIndex = new Map<number, number>()
  let tooLarge = false
  for (let id = 1; id < objectCount; id++) {
    offsets[id] = pairList.length / 2
    if (tooLarge) continue
    pdb.enumObjectProperties(id, (attrId, valueId) => {
      if (pairList.length / 2 >= maxPairs) {
        tooLarge = true
        return
      }
      let index = valueIndex.get(valueId)
      if (index === undefined) {
        index = values.length
        values.push(pdb.getAttrValue(attrId, valueId))
        valueIndex.set(valueId, index)
      }
      pairList.push(attrId, index)
    })
  }
  offsets[objectCount] = pairList.length / 2
  if (tooLarge) return { ok: false, pairs: pairList.length / 2, limit: maxPairs }
  const attributes: PropertySnapshotAttribute[] = []
  pdb.enumAttributes((attrId, definition) => {
    attributes[attrId] = {
      name: String(definition.name || ''),
      category: String(definition.category || ''),
      displayName: String(definition.displayName || definition.name || ''),
      hidden: ((definition.flags || 0) & 1) === 1,
    }
  })
  for (let index = 0; index < attributes.length; index++) {
    if (!attributes[index]) {
      attributes[index] = { name: '', category: '', displayName: '', hidden: true }
    }
  }
  return {
    ok: true,
    objectCount,
    attributes,
    offsets,
    pairs: new Int32Array(pairList),
    values,
  }
}

function isSnapshotExport(value: unknown): value is PropertySnapshotExport {
  if (typeof value !== 'object' || value === null || !('ok' in value)) return false
  if (value.ok === false) return 'pairs' in value && typeof value.pairs === 'number'
  return (
    'offsets' in value &&
    value.offsets instanceof Int32Array &&
    'pairs' in value &&
    value.pairs instanceof Int32Array &&
    'attributes' in value &&
    Array.isArray(value.attributes) &&
    'values' in value &&
    Array.isArray(value.values)
  )
}

export async function loadPropertySnapshot(
  model: ViewerAgentModel,
  maxPairs: number,
): Promise<PropertySnapshot> {
  const result: unknown = await model
    .getPropertyDb()
    .executeUserFunction(exportPropertySnapshot, maxPairs)
  if (!isSnapshotExport(result)) throw new Error('the property database export was unreadable')
  if (!result.ok) {
    throw new Error(
      `this model's property database is too large for run_query (more than ${result.limit} properties); use find_elements and get_properties instead`,
    )
  }
  return result
}

export type QueryWorkerRequest =
  | { kind: 'load'; snapshot: PropertySnapshot; elements: readonly ElementRow[] }
  | { kind: 'run'; id: number; code: string; maxChars: number }

export type QueryRunResult =
  | { ok: true; text: string; count: number | null; truncated: boolean; logs: string[] }
  | { ok: false; error: string; logs: string[] }

export type QueryWorkerResponse =
  | { kind: 'loaded' }
  | { kind: 'result'; id: number; result: QueryRunResult }

export interface QueryWorkerScope {
  onmessage: ((event: { data: QueryWorkerRequest }) => void) | null
  postMessage(message: QueryWorkerResponse): void
}

type QueryConsole = {
  [method in 'log' | 'info' | 'warn' | 'error' | 'debug']: (...args: unknown[]) => void
}

// The sandbox worker's entry point, serialized with Function.prototype.toString: it must stay
// self-contained. It strips the network and storage globals before evaluating any query.
export const runQueryWorker = (scope: QueryWorkerScope): void => {
  const post = scope.postMessage.bind(scope)
  const blocked = [
    'fetch',
    'XMLHttpRequest',
    'WebSocket',
    'WebTransport',
    'EventSource',
    'importScripts',
    'indexedDB',
    'caches',
    'BroadcastChannel',
    'Worker',
    'SharedWorker',
    'postMessage',
  ]
  for (const name of blocked) {
    let target: object | null = scope
    while (target) {
      if (Object.hasOwn(target, name)) Reflect.deleteProperty(target, name)
      target = Object.getPrototypeOf(target)
    }
  }

  let snapshot: PropertySnapshot | null = null
  let elements: readonly ElementRow[] = []
  let instanceOf = -1
  const internal = (category: string) => category.startsWith('__') && category !== '__category__'
  const AsyncFunction: FunctionConstructor = new Function(
    'return (async function () {}).constructor',
  )()

  const collect = (id: number, into: Map<string, PropertyValue>, depth: number): void => {
    if (!snapshot || id < 1 || id >= snapshot.objectCount) return
    const start = snapshot.offsets[id]
    const end = snapshot.offsets[id + 1]
    if (depth < 2 && instanceOf >= 0) {
      for (let pair = start; pair < end; pair++) {
        if (snapshot.pairs[pair * 2] !== instanceOf) continue
        const parent = snapshot.values[snapshot.pairs[pair * 2 + 1]]
        if (typeof parent === 'number') collect(parent, into, depth + 1)
      }
    }
    for (let pair = start; pair < end; pair++) {
      const attribute = snapshot.attributes[snapshot.pairs[pair * 2]]
      if (!attribute || attribute.hidden || internal(attribute.category)) continue
      into.set(attribute.displayName, snapshot.values[snapshot.pairs[pair * 2 + 1]])
    }
  }

  const pdb = {
    get objectCount(): number {
      return snapshot ? snapshot.objectCount : 0
    },
    elements: () => elements.map((row) => ({ ...row })),
    leaves: () => elements.map((row) => row.dbId),
    name: (id: number) => elements.find((row) => row.dbId === id)?.name ?? '',
    props: (id: number) => {
      const map = new Map<string, PropertyValue>()
      collect(id, map, 0)
      return Object.fromEntries(map)
    },
    prop: (id: number, name: string) => {
      const map = new Map<string, PropertyValue>()
      collect(id, map, 0)
      return map.get(name)
    },
    find: (predicate: (id: number, db: unknown) => boolean): number[] =>
      elements.filter((row) => predicate(row.dbId, pdb)).map((row) => row.dbId),
    attributes: () => {
      const names = new Set<string>()
      for (const attribute of snapshot?.attributes ?? []) {
        if (!attribute.hidden && !internal(attribute.category)) {
          names.add(attribute.displayName)
        }
      }
      return [...names].sort()
    },
    getObjectCount: () => (snapshot ? snapshot.objectCount : 0),
    enumObjectProperties: (id: number, callback: (attrId: number, valueId: number) => void) => {
      if (!snapshot || id < 1 || id >= snapshot.objectCount) return
      for (let pair = snapshot.offsets[id]; pair < snapshot.offsets[id + 1]; pair++) {
        callback(snapshot.pairs[pair * 2], snapshot.pairs[pair * 2 + 1])
      }
    },
    getAttributeDef: (attrId: number) => snapshot?.attributes[attrId],
    getAttrValue: (_attrId: number, valueId: number) => snapshot?.values[valueId],
  }

  const describe = (value: unknown): string => {
    if (typeof value === 'string') return value
    try {
      return String(JSON.stringify(value))
    } catch {
      return String(value)
    }
  }

  const replacer = (_key: string, value: unknown) => {
    if (value instanceof Map) return Object.fromEntries(value)
    if (value instanceof Set) return [...value]
    if (value instanceof Int32Array || value instanceof Float64Array) return [...value]
    if (typeof value === 'bigint') return value.toString()
    return value
  }

  const compile = (code: string) => {
    const trimmed = code.trim().replace(/;+\s*$/, '')
    try {
      const expression = new Function('pdb', 'console', `"use strict";\nreturn (\n${trimmed}\n);`)
      return (log: QueryConsole) => {
        const value = expression(pdb, log)
        return typeof value === 'function' ? value(pdb, log) : value
      }
    } catch {
      const body = new AsyncFunction('pdb', 'console', `"use strict";\n${code}`)
      return (log: QueryConsole) => body(pdb, log)
    }
  }

  scope.onmessage = (event) => {
    const message = event.data
    if (message.kind === 'load') {
      snapshot = message.snapshot
      elements = message.elements
      instanceOf = snapshot.attributes.findIndex((item) => item.category === '__instanceof__')
      post({ kind: 'loaded' })
      return
    }
    const { id, maxChars } = message
    const logs: string[] = []
    const capture = (...args: unknown[]) => {
      if (logs.length < 50) logs.push(args.map(describe).join(' ').slice(0, 500))
    }
    const log: QueryConsole = {
      log: capture,
      info: capture,
      warn: capture,
      error: capture,
      debug: capture,
    }
    Promise.resolve()
      .then(() => {
        if (!snapshot) throw new Error('no property database is loaded')
        return compile(message.code)(log)
      })
      .then((value) => {
        const text =
          value === undefined
            ? 'undefined'
            : typeof value === 'string'
              ? value
              : String(JSON.stringify(value, replacer))
        post({
          kind: 'result',
          id,
          result: {
            ok: true,
            text: text.slice(0, maxChars),
            count: Array.isArray(value) ? value.length : null,
            truncated: text.length > maxChars,
            logs,
          },
        })
      })
      .catch((error: unknown) => {
        post({
          kind: 'result',
          id,
          result: {
            ok: false,
            error: error instanceof Error ? `${error.name}: ${error.message}` : describe(error),
            logs,
          },
        })
      })
  }
}

export interface QueryWorkerHandle {
  post(message: QueryWorkerRequest): void
  listen(
    onMessage: (message: QueryWorkerResponse) => void,
    onError: (message: string) => void,
  ): void
  terminate(): void
}

export function queryWorkerSource(): string {
  return `"use strict";\n(${String(runQueryWorker)})(self);\n`
}

export function createBrowserQueryWorker(): QueryWorkerHandle {
  const url = URL.createObjectURL(new Blob([queryWorkerSource()], { type: 'text/javascript' }))
  const worker = new Worker(url)
  return {
    post: (message) => worker.postMessage(message),
    listen: (onMessage, onError) => {
      worker.onmessage = (event: MessageEvent<QueryWorkerResponse>) => onMessage(event.data)
      worker.onerror = (event) => {
        event.preventDefault()
        onError(event.message || 'the query worker failed')
      }
    },
    terminate: () => {
      worker.terminate()
      URL.revokeObjectURL(url)
    },
  }
}

export interface QueryRunRequest {
  key: number
  snapshot: PropertySnapshot
  elements: readonly ElementRow[]
  code: string
  timeoutMs: number
  maxChars: number
  signal: AbortSignal
}

/** One worker per sandbox, holding the latest model's snapshot. A query that overruns its
 * time box, or is cancelled, terminates the worker; the next query starts a fresh one. */
export class QuerySandbox {
  private worker: QueryWorkerHandle | null = null
  private loadedKey: number | null = null
  private sequence = 0
  private pending = new Map<number, (result: QueryRunResult) => void>()
  private readonly createWorker: () => QueryWorkerHandle

  constructor(createWorker: () => QueryWorkerHandle = createBrowserQueryWorker) {
    this.createWorker = createWorker
  }

  run(request: QueryRunRequest): Promise<QueryRunResult> {
    if (request.signal.aborted) return Promise.resolve({ ok: false, error: 'cancelled', logs: [] })
    const worker = this.ensureWorker()
    if (this.loadedKey !== request.key) {
      worker.post({ kind: 'load', snapshot: request.snapshot, elements: request.elements })
      this.loadedKey = request.key
    }
    this.sequence += 1
    const id = this.sequence
    return new Promise((resolve) => {
      const finish = (result: QueryRunResult) => {
        clearTimeout(timer)
        request.signal.removeEventListener('abort', onAbort)
        this.pending.delete(id)
        resolve(result)
      }
      const stop = (error: string) => {
        this.reset()
        finish({ ok: false, error, logs: [] })
      }
      const onAbort = () => stop('cancelled')
      const timer = setTimeout(
        () => stop(`timed out after ${request.timeoutMs} ms; the query was stopped`),
        request.timeoutMs,
      )
      request.signal.addEventListener('abort', onAbort, { once: true })
      this.pending.set(id, finish)
      worker.post({ kind: 'run', id, code: request.code, maxChars: request.maxChars })
    })
  }

  dispose(): void {
    this.reset()
  }

  private ensureWorker(): QueryWorkerHandle {
    if (this.worker) return this.worker
    const worker = this.createWorker()
    worker.listen(
      (message) => {
        if (message.kind === 'result') this.pending.get(message.id)?.(message.result)
      },
      (error) => {
        const waiting = [...this.pending.values()]
        this.reset()
        for (const finish of waiting) finish({ ok: false, error, logs: [] })
      },
    )
    this.worker = worker
    return worker
  }

  private reset(): void {
    this.worker?.terminate()
    this.worker = null
    this.loadedKey = null
  }
}
